// ---------- Pose templates per exercise ----------
const FL=93;
const s=(hip,torso,arms,legs,x)=>Object.assign({v:'s',hip,torso,arms,legs},x||{});
const f=(hip,arms,legs,x)=>Object.assign({v:'f',hip,arms,legs},x||{});
const fr=(pose,props,arrows)=>({pose,props:props||[],arrows:arrows||[]});
