const R_=Math.PI/180,D_=180/Math.PI;
// 2-segment inverse kinematics: origin o, target t, lengths l1,l2, bend sign (+1 rotates the first segment clockwise = toward +x when pointing down)
function ik2(o,t,l1,l2,bend){ const dx=t[0]-o[0],dy=t[1]-o[1]; let d=Math.hypot(dx,dy); const mx=l1+l2-0.3; if(d>mx)d=mx; if(d<1)d=1; const at=Math.atan2(dx,dy)*D_; const c=Math.max(-1,Math.min(1,(l1*l1+d*d-l2*l2)/(2*l1*d))); const al=Math.acos(c)*D_; const a1=at+(bend==null?1:bend)*al; const e=[o[0]+Math.sin(a1*R_)*l1,o[1]+Math.cos(a1*R_)*l1]; const a2=Math.atan2(t[0]-e[0],t[1]-e[1])*D_; return [Math.round(a1*10)/10,Math.round(a2*10)/10]; }
const shS=(hip,t)=>[hip[0]+Math.sin(t*R_)*24,hip[1]+Math.cos(t*R_)*24];
const armTo=(sh,hand,bend)=>ik2(sh,hand,16,14,bend==null?-1:bend);
const legTo=(hip,ankle,bend,foot)=>ik2(hip,ankle,21,19,bend==null?1:bend).concat([foot===undefined?90:foot]); // foot null = neutral ankle (toes perpendicular to the shin)
// side pose by joint targets: sp(hip,torso,{h:hand|[h0,h1], hb:bend|[b0,b1], a:ankle|[a0,a1], ab:bend|[b0,b1], foot:f|[f0,f1], arms:[raw], legs:[raw], head, flip, tilt, rot})
function sp(hip,torso,c){ c=c||{}; const sh=shS(hip,torso); const two=(v)=>v==null?[null,null]:(Array.isArray(v)&&Array.isArray(v[0]))?v:[v,v]; const tw=(v)=>Array.isArray(v)?v:[v,v];
  const H=two(c.h),A=two(c.a),hb=tw(c.hb),ab=tw(c.ab),ft=tw(c.foot);
  const arms=c.arms||H.map((p,i)=>p?armTo(sh,p,hb[i]):(c.legs&&c.legs[i])?[0,0]:[5,5]); const legs=c.legs||A.map((p,i)=>p?legTo(hip,p,ab[i],ft[i]):[0,0,90]);
  const x={}; ['head','headTilt','flip','tilt','rot'].forEach(k=>{if(c[k]!=null)x[k]=c[k];}); return s(hip,torso,arms,legs,x); }
